class Solution {
public:
    int missingNumber(vector<int>& nums) {
        int n = nums.size();
        int result = n;                     // start with n because indices go 0..n-1
        for (int i = 0; i < n; ++i) {
            result ^= i;                    // cancel index i
            result ^= nums[i];              // cancel present number
        }
        return result;                      // the only uncancelled value
    }
};
